def create_tls_context():
    """Create a TLS context that supports TLS 1.3 and allows post-handshake auth extension."""
    ctx = ssl.SSLContext(ssl.PROTOCOL_TLS_CLIENT)
    ctx.minimum_version = ssl.TLSVersion.TLSv1_3
    ctx.maximum_version = ssl.TLSVersion.TLSv1_3
    # Enable post-handshake auth extension to trigger server behavior
    ctx.post_handshake_auth = True
    ctx.check_hostname = False
    ctx.verify_mode = ssl.CERT_NONE
    return ctx

def send_http2_request(conn, stream_id, host, path):
    """Send a basic HTTP/2 GET request."""
    headers = [
        (':method', 'GET'),
        (':path', path),
        (':scheme', 'https'),
        (':authority', host),
        ('user-agent', 'PoC-Client/1.0')
    ]
    conn.send_headers(stream_id, headers)
    conn.send_data(stream_id, b'', end_stream=True)

